CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RefreshToken" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "tokenHash" TEXT NOT NULL UNIQUE, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Profile" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE, "goals" TEXT NOT NULL DEFAULT '[]', "proficiency" TEXT NOT NULL DEFAULT 'beginner', "dailyMinutes" INTEGER NOT NULL DEFAULT 15, "timezone" TEXT NOT NULL DEFAULT 'UTC', "ieltsIntent" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Course" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "level" TEXT NOT NULL, "position" INTEGER NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Lesson" ("id" TEXT PRIMARY KEY, "courseId" TEXT NOT NULL REFERENCES "Course"("id") ON DELETE CASCADE, "title" TEXT NOT NULL, "summary" TEXT NOT NULL, "content" TEXT NOT NULL, "durationMin" INTEGER NOT NULL, "position" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("courseId", "position"));
CREATE TABLE "LessonProgress" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "lessonId" TEXT NOT NULL REFERENCES "Lesson"("id") ON DELETE CASCADE, "completedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("userId", "lessonId"));
CREATE TABLE "VocabularyItem" ("id" TEXT PRIMARY KEY, "word" TEXT NOT NULL UNIQUE, "partOfSpeech" TEXT NOT NULL, "definition" TEXT NOT NULL, "example" TEXT NOT NULL, "level" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ReviewSchedule" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "vocabularyId" TEXT NOT NULL REFERENCES "VocabularyItem"("id") ON DELETE CASCADE, "dueAt" TIMESTAMP(3) NOT NULL, "intervalDays" INTEGER NOT NULL DEFAULT 0, "repetitions" INTEGER NOT NULL DEFAULT 0, "lastGrade" TEXT, "lastReviewedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("userId", "vocabularyId"));
CREATE TABLE "SpeakingSession" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "type" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'draft', "prompt" TEXT NOT NULL, "transcript" TEXT, "feedback" TEXT, "audioUrl" TEXT, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "deletedAt" TIMESTAMP(3));
CREATE TABLE "Conversation" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "scenarioId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'active', "summary" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" TIMESTAMP(3));
CREATE TABLE "ConversationTurn" ("id" TEXT PRIMARY KEY, "conversationId" TEXT NOT NULL REFERENCES "Conversation"("id") ON DELETE CASCADE, "role" TEXT NOT NULL, "transcript" TEXT, "text" TEXT NOT NULL, "audioUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "IeltsAttempt" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "mockId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'in_progress', "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "finishedAt" TIMESTAMP(3), "feedback" TEXT);
CREATE TABLE "IeltsAttemptResponse" ("id" TEXT PRIMARY KEY, "attemptId" TEXT NOT NULL REFERENCES "IeltsAttempt"("id") ON DELETE CASCADE, "sectionId" TEXT NOT NULL, "transcript" TEXT, "audioUrl" TEXT, "feedback" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("attemptId", "sectionId"));
CREATE TABLE "SkillSnapshot" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "skill" TEXT NOT NULL, "value" DOUBLE PRECISION, "source" TEXT NOT NULL, "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "StreakState" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE, "currentDays" INTEGER NOT NULL DEFAULT 0, "longestDays" INTEGER NOT NULL DEFAULT 0, "lastActivityOn" TIMESTAMP(3), "reminderTime" TEXT, "reminderDays" TEXT NOT NULL DEFAULT '[]', "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Referral" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE, "code" TEXT NOT NULL UNIQUE, "referredById" TEXT, "redeemedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "PurchaseEntitlement" ("id" TEXT PRIMARY KEY, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "productId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'inactive', "source" TEXT NOT NULL, "purchaseToken" TEXT UNIQUE, "startsAt" TIMESTAMP(3), "expiresAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "RefreshToken_userId_expiresAt_idx" ON "RefreshToken"("userId", "expiresAt"); CREATE INDEX "LessonProgress_userId_completedAt_idx" ON "LessonProgress"("userId", "completedAt"); CREATE INDEX "ReviewSchedule_userId_dueAt_idx" ON "ReviewSchedule"("userId", "dueAt"); CREATE INDEX "SpeakingSession_userId_startedAt_idx" ON "SpeakingSession"("userId", "startedAt"); CREATE INDEX "Conversation_userId_createdAt_idx" ON "Conversation"("userId", "createdAt"); CREATE INDEX "ConversationTurn_conversationId_createdAt_idx" ON "ConversationTurn"("conversationId", "createdAt"); CREATE INDEX "IeltsAttempt_userId_startedAt_idx" ON "IeltsAttempt"("userId", "startedAt"); CREATE INDEX "SkillSnapshot_userId_skill_recordedAt_idx" ON "SkillSnapshot"("userId", "skill", "recordedAt"); CREATE INDEX "Referral_referredById_idx" ON "Referral"("referredById"); CREATE INDEX "PurchaseEntitlement_userId_status_expiresAt_idx" ON "PurchaseEntitlement"("userId", "status", "expiresAt");
